std::span<const AbilityId> ability_ids() {
  return kIds;
}
std::string ability_name(AbilityId id, Locale locale) {
  for (const auto& entry : kNames) {
    if (entry.id == id)
      return entry.names[static_cast<unsigned>(locale)];
  }
  return "ID " + std::to_string(id);
}
